//! The Seeker look: emulator skin (phone frame) and the on-device theme (dark mode, Solana-purple
//! system palette, wallpaper). All our own artwork; no Solana Mobile logos (decision D6).

use std::path::PathBuf;

use anyhow::{Context, Result};

use crate::adb::Adb;
use crate::{emulator, profile, SmsPaths};

/// Skin files, generated by profiles/seeker/skin/make-skin.swift and embedded in the binary.
const SKIN_FILES: &[(&str, &[u8])] = &[
    ("layout", include_bytes!("../../../profiles/seeker/skin/layout")),
    ("back.png", include_bytes!("../../../profiles/seeker/skin/back.png")),
    ("mask.png", include_bytes!("../../../profiles/seeker/skin/mask.png")),
];

/// Material You seed color: Solana purple.
pub const PALETTE_HEX: &str = "9945FF";

pub fn skin_dir(sms: &SmsPaths) -> PathBuf {
    sms.home.join("skins/seeker")
}

/// Writes the skin to `~/.sms/skins/seeker` and points the AVD at it.
pub fn install_skin(sms: &SmsPaths, avd: &str) -> Result<()> {
    let dir = skin_dir(sms);
    std::fs::create_dir_all(&dir)?;
    for (name, bytes) in SKIN_FILES {
        std::fs::write(dir.join(name), bytes).with_context(|| format!("writing skin file {name}"))?;
    }
    let path = dir.to_string_lossy().to_string();
    emulator::set_avd_config(avd, &[("skin.name", "seeker"), ("skin.path", &path), ("skin.dynamic", "no"), ("showDeviceFrame", "yes")])
}

/// Dark mode + Solana-purple palette + wallpaper (wallpaper needs the SMS Test Wallet app).
pub fn apply_device_theme(adb: &Adb) -> Result<bool> {
    adb.shell("cmd uimode night yes")?;
    let overlay = format!(
        "{{\"android.theme.customization.system_palette\":\"{PALETTE_HEX}\",\
          \"android.theme.customization.accent_color\":\"{PALETTE_HEX}\",\
          \"android.theme.customization.color_source\":\"preset\",\
          \"android.theme.customization.theme_style\":\"TONAL_SPOT\"}}"
    );
    adb.shell(&format!("settings put secure theme_customization_overlay_packages '{overlay}'"))?;
    if adb.has_package(profile::SMS_WALLET_PACKAGE) {
        adb.shell(&format!("am start -W -n {}/.ThemeActivity", profile::SMS_WALLET_PACKAGE))?;
        Ok(true)
    } else {
        Ok(false)
    }
}

pub fn is_themed(adb: &Adb) -> bool {
    adb.shell("settings get secure theme_customization_overlay_packages")
        .map(|v| v.contains(PALETTE_HEX))
        .unwrap_or(false)
}
